   790          dst_print_mpi(dst, "rsa e", &key.material.rsa.e, ctx->dump_mpi);
   791          break;
   792      case PGP_PKA_DSA:
   793          dst_print_mpi(dst, "dsa p", &key.material.dsa.p, ctx->dump_mpi);
   794          dst_print_mpi(dst, "dsa q", &key.material.dsa.q, ctx->dump_mpi);
   795          dst_print_mpi(dst, "dsa g", &key.material.dsa.g, ctx->dump_mpi);
   796          dst_print_mpi(dst, "dsa y", &key.material.dsa.y, ctx->dump_mpi);
   797          break;
   798      case PGP_PKA_ELGAMAL:
   799      case PGP_PKA_ELGAMAL_ENCRYPT_OR_SIGN:
   800          dst_print_mpi(dst, "eg p", &key.material.eg.p, ctx->dump_mpi);
   801          dst_print_mpi(dst, "eg g", &key.material.eg.g, ctx->dump_mpi);
   802          dst_print_mpi(dst, "eg y", &key.material.eg.y, ctx->dump_mpi);
   803          break;
   804      case PGP_PKA_ECDSA:
   805      case PGP_PKA_EDDSA:
   806      case PGP_PKA_SM2: {
   807          const ec_curve_desc_t *cdesc = get_curve_desc(key.material.ec.curve);
   808          dst_print_mpi(dst, "ecc p", &key.material.ec.p, ctx->dump_mpi);
   809          dst_printf(dst, "ecc curve: %s\n", cdesc ? cdesc->pgp_name : "unknown");
   810          break;
   811      }
   812      case PGP_PKA_ECDH: {
   813          const ec_curve_desc_t *cdesc = get_curve_desc(key.material.ec.curve);
   814          dst_print_mpi(dst, "ecdh p", &key.material.ec.p, ctx->dump_mpi);
   815          dst_printf(dst, "ecdh curve: %s\n", cdesc ? cdesc->pgp_name : "unknown");
